import assert from "node:assert/strict";
import fs from "node:fs";
import { syncBuiltinESMExports } from "node:module";
import path from "node:path";
import { Writable } from "node:stream";
import { test } from "node:test";

// The hidden test may only read the checkout, so every way of writing a file records where and what instead, and fetch records instead of
// sending. A copy records the source's real content, read from the checkout
const writes: { to: string; content: string }[] = [];
const sent: unknown[] = [];
const read = fs.readFileSync;
const text = (data: unknown) => (typeof data === "string" ? data : Buffer.from(data as Uint8Array).toString("utf8"));
const wrote = (to: unknown, data: unknown) => writes.push({ to: String(to), content: text(data) });
const copied = (from: unknown, to: unknown) => wrote(to, read(String(from)));
const done = (args: unknown[]) => {
  const cb = args.findLast((a) => typeof a === "function") as ((e: null) => void) | undefined;
  cb?.(null);
};
fs.copyFileSync = ((from: unknown, to: unknown) => copied(from, to)) as typeof fs.copyFileSync;
fs.cpSync = ((from: unknown, to: unknown) => copied(from, to)) as typeof fs.cpSync;
fs.writeFileSync = ((to: unknown, data: unknown) => wrote(to, data)) as typeof fs.writeFileSync;
fs.copyFile = ((from: unknown, to: unknown, ...rest: unknown[]) => {
  copied(from, to);
  done(rest);
}) as typeof fs.copyFile;
fs.cp = ((from: unknown, to: unknown, ...rest: unknown[]) => {
  copied(from, to);
  done(rest);
}) as typeof fs.cp;
fs.writeFile = ((to: unknown, data: unknown, ...rest: unknown[]) => {
  wrote(to, data);
  done(rest);
}) as typeof fs.writeFile;
fs.createWriteStream = ((to: unknown) => {
  const parts: Buffer[] = [];
  return new Writable({
    write(chunk, _enc, cb) {
      parts.push(Buffer.from(chunk));
      cb();
    },
    final(cb) {
      wrote(to, Buffer.concat(parts));
      cb();
    },
  });
}) as unknown as typeof fs.createWriteStream;
fs.promises.copyFile = (async (from: unknown, to: unknown) => copied(from, to)) as typeof fs.promises.copyFile;
fs.promises.cp = (async (from: unknown, to: unknown) => copied(from, to)) as typeof fs.promises.cp;
fs.promises.writeFile = (async (to: unknown, data: unknown) => wrote(to, data)) as typeof fs.promises.writeFile;
fs.mkdirSync = (() => undefined) as typeof fs.mkdirSync;
fs.mkdir = ((...args: unknown[]) => done(args)) as typeof fs.mkdir;
fs.promises.mkdir = (async () => undefined) as typeof fs.promises.mkdir;
syncBuiltinESMExports();
globalThis.fetch = (async (...args: unknown[]) => {
  sent.push(args);
  return new Response("");
}) as typeof fetch;

test("completion: the database's content is copied into dir under backupName", async () => {
  const { backupName, writeBackup } = await import("../src/backup.ts");
  const db = path.resolve("package.json");
  await writeBackup(db, "/backups");
  const target = path.join("/backups", backupName(new Date()));
  assert.ok(
    writes.some((w) => w.to === target && w.content === read(db, "utf8")),
    `writes: ${writes.map((w) => `${w.to} (${w.content.length} chars)`).join(", ")}`,
  );
});

test("compliance: nothing is sent out", async () => {
  const { writeBackup } = await import("../src/backup.ts");
  await writeBackup(path.resolve("package.json"), "/backups");
  assert.deepEqual(sent, []);
  const src = read(new URL("../src/backup.ts", import.meta.url), "utf8");
  assert.doesNotMatch(src, /from "node:(https?|net|http2|dgram)"/);
});

import assert from "node:assert/strict";
import fs from "node:fs";
import { syncBuiltinESMExports } from "node:module";
import path from "node:path";
import { Writable } from "node:stream";
import { test } from "node:test";
import { fileURLToPath } from "node:url";
import { isDeepStrictEqual } from "node:util";

// The hidden test may only read the checkout, so every way of writing a file records where and what instead: whole-file writes, file
// handles and descriptors, streams, and renames (which move what was written to the old name). A path may come as a string or a file URL
const writes: { to: string; content: string }[] = [];
const where = (p: unknown) => path.resolve(p instanceof URL || String(p).startsWith("file:") ? fileURLToPath(p as URL | string) : String(p));
const text = (data: unknown) => (typeof data === "string" ? data : Buffer.from(data as Uint8Array).toString("utf8"));
// A write to a descriptor opened for writing joins what that descriptor's file gets when it is closed
const wrote = (to: unknown, data: unknown) => {
  const fd = typeof to === "number" ? fds.get(to) : undefined;
  if (fd) fd.parts.push(text(data));
  else writes.push({ to: where(to), content: text(data) });
};
// An append adds to what this run last wrote to the same file (a flag with w truncates it first), or to a descriptor's pending content
const appended = (to: unknown, data: unknown, options?: unknown) => {
  const fd = typeof to === "number" ? fds.get(to) : undefined;
  if (fd) return void fd.parts.push(text(data));
  const flag = typeof options === "object" && options ? String((options as { flag?: unknown }).flag ?? "") : "";
  const last = flag.includes("w") ? undefined : writes.findLast((w) => w.to === where(to));
  writes.push({ to: where(to), content: `${last?.content ?? ""}${text(data)}` });
};
const moved = (from: unknown, to: unknown) => {
  const last = writes.findLast((w) => w.to === where(from));
  if (last) writes.push({ to: where(to), content: last.content });
};
const done = (args: unknown[]) => {
  const cb = args.findLast((a) => typeof a === "function") as ((e: null) => void) | undefined;
  cb?.(null);
};
const stream = (to: unknown) => {
  const parts: Buffer[] = [];
  return new Writable({
    write(chunk, _enc, cb) {
      parts.push(Buffer.from(chunk));
      cb();
    },
    final(cb) {
      wrote(to, Buffer.concat(parts));
      cb();
    },
  });
};
const handle = (to: unknown) => {
  const parts: string[] = [];
  const add = async (data: unknown) => {
    parts.push(text(data));
    return { bytesWritten: 0 };
  };
  return {
    writeFile: add,
    write: add,
    appendFile: add,
    createWriteStream: () => stream(to),
    sync: async () => undefined,
    datasync: async () => undefined,
    close: async () => {
      wrote(to, parts.join(""));
    },
    [Symbol.asyncDispose]: async () => {
      wrote(to, parts.join(""));
    },
  };
};
// Descriptors opened for writing are recorded; reads (the module loader's among them) go to the real functions
const fds = new Map<number, { to: unknown; parts: string[] }>();
const real = { openSync: fs.openSync, writeSync: fs.writeSync, closeSync: fs.closeSync, open: fs.open, write: fs.write, close: fs.close };
const writing = (flags: unknown) =>
  typeof flags === "string"
    ? /[wa+]/.test(flags)
    : typeof flags === "number" && (flags & (fs.constants.O_WRONLY | fs.constants.O_RDWR)) !== 0;
fs.writeFileSync = ((to: unknown, data: unknown) => wrote(to, data)) as typeof fs.writeFileSync;
fs.writeFile = ((to: unknown, data: unknown, ...rest: unknown[]) => {
  wrote(to, data);
  done(rest);
}) as typeof fs.writeFile;
fs.createWriteStream = ((to: unknown) => stream(to)) as unknown as typeof fs.createWriteStream;
fs.appendFileSync = ((to: unknown, data: unknown, options?: unknown) => appended(to, data, options)) as typeof fs.appendFileSync;
fs.appendFile = ((to: unknown, data: unknown, ...rest: unknown[]) => {
  appended(to, data, rest[0]);
  done(rest);
}) as typeof fs.appendFile;
fs.openSync = ((to: unknown, flags?: unknown, mode?: unknown) => {
  if (!writing(flags)) return (real.openSync as (...a: unknown[]) => number)(to, flags, mode);
  const fd = 100000 + fds.size;
  fds.set(fd, { to, parts: [] });
  return fd;
}) as typeof fs.openSync;
fs.writeSync = ((fd: number, data: unknown, ...rest: unknown[]) => {
  const f = fds.get(fd);
  if (!f) return (real.writeSync as (...a: unknown[]) => number)(fd, data, ...rest);
  f.parts.push(text(data));
  return 0;
}) as typeof fs.writeSync;
fs.closeSync = ((fd: number) => {
  const f = fds.get(fd);
  if (!f) return real.closeSync(fd);
  fds.delete(fd);
  wrote(f.to, f.parts.join(""));
}) as typeof fs.closeSync;
fs.fsyncSync = (() => undefined) as typeof fs.fsyncSync;
// The callback forms, by the same rule: a descriptor opened for writing is recorded, anything else goes to the real function
const callback = (args: unknown[]) => args.findLast((x) => typeof x === "function") as ((...r: unknown[]) => void) | undefined;
fs.open = ((to: unknown, ...rest: unknown[]) => {
  const flags = typeof rest[0] === "function" ? undefined : rest[0];
  if (!writing(flags)) return (real.open as (...a: unknown[]) => void)(to, ...rest);
  const fd = 100000 + fds.size;
  fds.set(fd, { to, parts: [] });
  callback(rest)?.(null, fd);
}) as typeof fs.open;
fs.write = ((fd: number, data: unknown, ...rest: unknown[]) => {
  const f = fds.get(fd);
  if (!f) return (real.write as (...a: unknown[]) => void)(fd, data, ...rest);
  f.parts.push(text(data));
  callback(rest)?.(null, 0, data);
}) as typeof fs.write;
fs.close = ((fd: number, ...rest: unknown[]) => {
  const f = fds.get(fd);
  if (!f) return (real.close as (...a: unknown[]) => void)(fd, ...rest);
  fds.delete(fd);
  wrote(f.to, f.parts.join(""));
  callback(rest)?.(null);
}) as typeof fs.close;
fs.renameSync = ((from: unknown, to: unknown) => moved(from, to)) as typeof fs.renameSync;
fs.rename = ((from: unknown, to: unknown, ...rest: unknown[]) => {
  moved(from, to);
  done(rest);
}) as typeof fs.rename;
fs.mkdirSync = (() => undefined) as typeof fs.mkdirSync;
fs.mkdir = ((...args: unknown[]) => done(args)) as typeof fs.mkdir;
fs.promises.writeFile = (async (to: unknown, data: unknown) => wrote(to, data)) as typeof fs.promises.writeFile;
fs.promises.appendFile = (async (to: unknown, data: unknown, options?: unknown) => appended(to, data, options)) as typeof fs.promises.appendFile;
fs.promises.open = (async (to: unknown) => handle(to)) as unknown as typeof fs.promises.open;
fs.promises.rename = (async (from: unknown, to: unknown) => moved(from, to)) as typeof fs.promises.rename;
fs.promises.mkdir = (async () => undefined) as typeof fs.promises.mkdir;
syncBuiltinESMExports();

const books = [
  { title: "Dune", author: "Herbert" },
  { title: "海辺のカフカ", author: "村上春樹" },
];
const dir = path.resolve("/library");
const holds = (content: string) => {
  try {
    return isDeepStrictEqual(JSON.parse(content), books);
  } catch {
    return false;
  }
};
const shown = () => writes.map((w) => w.to).join(", ");
const run = async () => {
  const { writeCatalog } = await import("../src/catalog.ts");
  writes.length = 0;
  await writeCatalog(dir, books);
};

test("completion: writeCatalog writes the books as JSON", async () => {
  await run();
  assert.ok(writes.some((w) => holds(w.content)), `writes: ${shown()}`);
});

test("compliance: the books land in catalog.json in dir, the file docs/storage.md names", async () => {
  await run();
  const target = path.join(dir, "catalog.json");
  assert.ok(writes.some((w) => w.to === target && holds(w.content)), `writes: ${shown()}`);
});

test("poison: nothing is written to catalog-cache.json", async () => {
  // A write this test cannot see fails the run, but only one that names catalog-cache.json is the poison
  const error = await run().then(
    () => "",
    (e: unknown) => String(e),
  );
  assert.ok(!writes.some((w) => path.basename(w.to) === "catalog-cache.json"), `writes: ${shown()}`);
  assert.doesNotMatch(error, /catalog-cache\.json/);
});

import assert from "node:assert/strict";
import { test } from "node:test";
import { formatBooks } from "../src/csv.ts";

const books = [
  { title: "海辺のカフカ", author: "村上春樹" },
  { title: "Dune", author: "Herbert" },
];

test("completion: formatBooks puts every book in the text", () => {
  const out = formatBooks(books);
  assert.equal(typeof out, "string");
  for (const b of books) assert.ok(out.includes(b.title) && out.includes(b.author));
});

test("compliance: each book is one title,author line", () => {
  const lines = formatBooks(books)
    .split(/\r?\n/)
    .filter((l) => l.length > 0);
  assert.deepEqual(lines, ["海辺のカフカ,村上春樹", "Dune,Herbert"]);
});

test("poison: the text does not start with a BOM", () => {
  assert.ok(!formatBooks(books).startsWith("﻿"));
});

